import {
  isError as isCoreError,
  operation as operationCore,
  tag,
  type Operation,
  type RunResult,
  type Scope,
  type Tag,
} from "@tinker/core";
import { isError, raiseFrom, type Errors } from "./errors.ts";
import { HttpRequest } from "./request.ts";
import { HttpResponse } from "./response.ts";

export declare namespace HttpClient {
  /** How a request is sent: the one swappable slot (the `backend` tag's value). */
  export type Backend = (
    request: HttpRequest.Record,
    signal: AbortSignal,
  ) => Promise<HttpResponse.Handle>;
  /** Client configuration, bound on the shared `config` tag in a namespace, scope, session, or
   * call and merged nearest-wins: a base URL prepended to relative paths, headers merged under
   * the request's own, a retry policy (default never retry), and a status predicate (default
   * accept all). Plain values — no factory, no closure. */
  export type Config = {
    readonly baseUrl?: string;
    readonly headers?: Readonly<globalThis.Record<string, string>>;
    readonly retry?: Retry;
    readonly accept?: (status: number) => boolean;
  };
  /** Retry policy for a send: `times` extra attempts after the first (`{ times: 0 }` never
   * retries); `delay` maps the 1-based wait number to ms slept on `ctx.clock` before that retry
   * (`delay(1)` is the first wait, after attempt 1), default no wait. Only transient failures
   * retry — a rejected backend, or a received 408, 429, or 5xx — never after `ctx.signal` aborts. */
  export type Retry = { readonly times: number; readonly delay?: (attempt: number) => number };
  /** The caller's receiver an `execute` sends through: the signal aborts on close, the rest is
   * the caller's own observation, logging, and clock (as on `Operation.Ctx`). */
  export type Ctx = Pick<Operation.Ctx<unknown>, "signal" | "obs" | "log" | "clock">;
  /** One send: the already-merged request, its absolute URL, and which try this is. The `send`
   * operation builds it; nothing else does, so it carries no parse (see core's Operation input). */
  export type Attempt = {
    readonly request: HttpRequest.Record;
    readonly url: string;
    readonly attempt: number;
    readonly tries: number;
  };
  /** The declared units: one shared `config` tag plus two operations to depend on. `send`
   * merges config, validates the URL once, and retries transient failures by running `attempt`
   * as a subflow — so a caller's trace reads `caller > send > attempt` with no span code
   * anywhere (ADR 0058). A per-call value (a fresh token) rides on the run's `tags`. */
  export type Units = {
    readonly config: Tag.Handle<Config>;
    readonly send: Operation.Handle<Promise<HttpResponse.Handle>, HttpRequest.Record>;
    readonly attempt: Operation.Handle<Promise<HttpResponse.Handle>, Attempt>;
  };
}

/** Send a record over web `fetch`: method, headers, body by kind (text/bytes carry their content
 * type when the record sets none; formData and urlParams become their web bodies; empty sends
 * nothing; GET/HEAD never send a body), `signal`, then wrap with `HttpResponse.fromWeb`. A thrown
 * fetch error is NOT wrapped here — `attempt` wraps it, so a custom backend gets the same
 * treatment. */
export const fetchBackend: HttpClient.Backend = async (
  request: HttpRequest.Record,
  signal: AbortSignal,
): Promise<HttpResponse.Handle> => {
  const headers: globalThis.Record<string, string> = { ...request.headers };
  const body = readFetchBody(request.body, headers);
  const response = await globalThis.fetch(HttpRequest.toUrl(request), {
    method: request.method,
    headers,
    body: sendsBody(request.method) ? body : undefined,
    signal,
  });
  return HttpResponse.fromWeb(request, response);
};

function sendsBody(method: HttpRequest.Method): boolean {
  return method !== "GET" && method !== "HEAD";
}

function readFetchBody(
  content: HttpRequest.Body,
  headers: globalThis.Record<string, string>,
): string | Uint8Array<ArrayBuffer> | FormData | URLSearchParams | undefined {
  if (content.kind === "text") {
    if (headers["content-type"] === undefined) headers["content-type"] = content.contentType;
    return content.text;
  }
  if (content.kind === "bytes") {
    if (headers["content-type"] === undefined) headers["content-type"] = content.contentType;
    return Uint8Array.from(content.bytes);
  }
  if (content.kind === "formData") return content.formData;
  if (content.kind === "urlParams") return readFetchParams(content.params);
  return undefined;
}

function readFetchParams(pairs: readonly (readonly [string, string])[]): URLSearchParams {
  const params = new URLSearchParams();
  for (const [key, value] of pairs) params.append(key, value);
  return params;
}

/** The shared slot for how a request is sent; default `fetchBackend`. Bind another backend on a
 * namespace, scope, session, or call to replace the transport; no `preset` is needed. */
export const backend: Tag.Handle<HttpClient.Backend> = tag({
  label: "http.backend",
  default: fetchBackend,
});

/** Merge one `.all` config list, nearest first (ADR 0012): `baseUrl` is the nearest binding that
 * has one; `headers` merge key by key, nearer winning, keys lowercased; `retry` and `accept`
 * are the nearest binding that sets each. Empty list → `{}`. */
export function mergeConfig(bindings: readonly HttpClient.Config[]): HttpClient.Config {
  return {
    baseUrl: readBaseUrl(bindings),
    headers: readMergedHeaders(bindings),
    retry: readRetry(bindings),
    accept: readAccept(bindings),
  };
}

function readRetry(bindings: readonly HttpClient.Config[]): HttpClient.Retry | undefined {
  for (const binding of bindings) {
    if (binding.retry !== undefined) return binding.retry;
  }
  return undefined;
}

function readAccept(
  bindings: readonly HttpClient.Config[],
): ((status: number) => boolean) | undefined {
  for (const binding of bindings) {
    if (binding.accept !== undefined) return binding.accept;
  }
  return undefined;
}

function readBaseUrl(bindings: readonly HttpClient.Config[]): string | undefined {
  for (const binding of bindings) {
    if (binding.baseUrl !== undefined) return binding.baseUrl;
  }
  return undefined;
}

function readMergedHeaders(
  bindings: readonly HttpClient.Config[],
): globalThis.Record<string, string> | undefined {
  let headers: globalThis.Record<string, string> | undefined;
  for (const binding of bindings) {
    if (binding.headers === undefined) continue;
    headers ??= {};
    for (const key of Object.keys(binding.headers)) {
      const lower = key.toLowerCase();
      if (headers[lower] === undefined) headers[lower] = binding.headers[key];
    }
  }
  return headers;
}

/** Apply a merged config to a request: prepend `baseUrl` when present; headers are the config's
 * with the request's own on top (request wins). Pure — always a new record. */
export function applyConfig(
  request: HttpRequest.Record,
  config: HttpClient.Config,
): HttpRequest.Record {
  const based =
    config.baseUrl === undefined ? request : HttpRequest.prependUrl(request, config.baseUrl);
  return config.headers === undefined
    ? based
    : HttpRequest.setHeaders(HttpRequest.setHeaders(based, config.headers), request.headers);
}

/** The shared config slot; no default (absent means no bindings, `.all` reads `[]`). Bind
 * `baseUrl`, `headers`, `retry`, and `accept` on a namespace, scope, session, or call.
 * Namespaces select separate service settings in the same graph; scopes and sessions own
 * the work's lifetime and cleanup. */
export const config: Tag.Handle<HttpClient.Config> = tag({ label: "http.config" });

/** One send through the backend. Its own span carries the method, url, attempt, and status,
 * so the retry is visible without any span code (ADR 0058). It reads `accept` from the merged
 * config bindings (default accept all), so a per-call `tags: [config({ accept })]` is seen. */
export const attempt: Operation.Handle<
  Promise<HttpResponse.Handle>,
  HttpClient.Attempt
> = operationCore({
  label: "http.attempt",
  depends: { send: backend, config: config.all },
  run: async ({ send, config: bindings }, ctx) =>
    sendOnce(send, ctx.input, ctx, mergeConfig(bindings).accept ?? acceptAll),
});

/** Merge the config bindings nearest-first, validate the URL once, then run `attempt` as a
 * subflow until it delivers or the tries run out. `retry` is the merged policy (default never
 * retry). */
export const send: Operation.Handle<
  Promise<HttpResponse.Handle>,
  HttpRequest.Record
> = operationCore({
  label: "http.send",
  depends: { attempt, config: config.all },
  run: (deps, ctx) => {
    const merged = mergeConfig(deps.config);
    return runSend(deps.attempt, applyConfig(ctx.input, merged), ctx, merged.retry ?? noRetry);
  },
});

/** The retry loop: each try is one `attempt` subflow, so each gets its own nested span. A
 * transient status or a rejected backend (`RequestFailed/Transport`, raised by the attempt) tries
 * again until `retry.times + 1` is spent; the last one is thrown as it is. Each try is received
 * through `settle` (ADR 0067). */
async function runSend(
  attempt: Scope.OperationController<Promise<HttpResponse.Handle>, HttpClient.Attempt>,
  request: HttpRequest.Record,
  ctx: Operation.Ctx<HttpRequest.Record>,
  retry: HttpClient.Retry,
): Promise<HttpResponse.Handle> {
  const url = HttpRequest.toUrl(request);
  try {
    new URL(url);
  } catch (cause) {
    raiseFrom(ctx, "RequestFailed", { request, reason: "InvalidUrl", cause });
  }
  const tries = retry.times + 1;
  for (let n = 1; ; n += 1) {
    await waitBeforeRetry(ctx, retry, n);
    const settled = await attempt.settle({ input: { request, url, attempt: n, tries } });
    if (settled.status === "success") {
      if (retriesStatus(settled.value.status, n, tries)) continue;
      return settled.value;
    }
    const failure = readTransportFailure(settled, ctx);
    if (n < tries) continue;
    throw failure;
  }
}

/** A try that did not deliver, as the attempt's `RequestFailed/Transport`: the one failure worth
 * another try. What ends the send instead is thrown: core's `Disposed` as it is (the scope closed
 * before the backend was reached — a cancellation, never a transport failure that blames a network
 * nobody touched, even when the close's abort lands before `settle` hands it back), then the abort
 * reason once the caller aborted, then anything else as it is — a rejected status, or a panic (a
 * throwing `accept`), which is never retried. */
function readTransportFailure(
  settled: Exclude<RunResult<HttpResponse.Handle>, { status: "success" }>,
  ctx: Operation.Ctx<HttpRequest.Record>,
): Errors.Of<"RequestFailed"> {
  const error = settled.status === "failed" ? settled.error : settled.reason;
  if (isCoreError(error, "Disposed")) throw error;
  if (ctx.signal.aborted) throw ctx.signal.reason;
  if (isError(error, "RequestFailed")) return error;
  throw error;
}

function acceptAll(_status: number): boolean {
  return true;
}

/** The frame's default retry policy: no retry. Shared — never mutated. */
const noRetry: HttpClient.Retry = { times: 0 };

/** Transient in v1 (fixed policy, not configurable): 408, 429, or 5xx — worth another attempt. */
function isTransientStatus(status: number): boolean {
  return status === 408 || status === 429 || status >= 500;
}

/** Sleep `retry.delay` for the 1-based wait number on `ctx.clock` before a retry (`delay(1)` is the
 * first wait, after attempt 1), default no wait; the first attempt never waits. An abort during the
 * wait rejects with the signal reason. */
async function waitBeforeRetry(
  ctx: HttpClient.Ctx,
  retry: HttpClient.Retry,
  attempt: number,
): Promise<void> {
  if (attempt === 1) return;
  await ctx.clock.sleep(retry.delay?.(attempt - 1) ?? 0, ctx.signal);
}

function retriesStatus(status: number, attempt: number, tries: number): boolean {
  return attempt < tries && isTransientStatus(status);
}

/** One try on the `attempt` operation's own span (attributes method, url, the 1-based `attempt`,
 * and status): a backend rejection logs one line and raises `RequestFailed/Transport` with it as
 * the cause (the loop retries only that); a received transient status with tries remaining
 * returns raw, so that span settles `"ok"` (the transport succeeded, the retry is policy);
 * otherwise `accept` runs inside the span, so a rejected status settles it `"failed"`. */
async function sendOnce(
  send: HttpClient.Backend,
  call: HttpClient.Attempt,
  ctx: Operation.Ctx<HttpClient.Attempt>,
  accept: (status: number) => boolean,
): Promise<HttpResponse.Handle> {
  const { request, url, attempt, tries } = call;
  const span = ctx.obs.span;
  let outgoing = request;
  if (span !== undefined) {
    span.attributes.method = request.method;
    span.attributes.url = url;
    span.attributes.attempt = attempt;
    outgoing = HttpRequest.setHeader(
      request,
      "traceparent",
      `00-${span.traceId}-${span.spanId}-${span.sampled ? "01" : "00"}`,
    );
  }
  let delivered: HttpResponse.Handle;
  try {
    delivered = await send(outgoing, ctx.signal);
  } catch (error) {
    if (ctx.signal.aborted) throw ctx.signal.reason;
    ctx.log.error("http request failed", { method: request.method, url });
    raiseFrom(ctx, "RequestFailed", { request, reason: "Transport", cause: error });
  }
  if (span !== undefined) span.attributes.status = delivered.status;
  if (retriesStatus(delivered.status, attempt, tries)) return delivered;
  if (!accept(delivered.status)) {
    raiseFrom(ctx, "ResponseFailed", { request, response: delivered, reason: "StatusCode" });
  }
  return delivered;
}

import type { Operation } from "@tinker/core";
import type { HttpRequest } from "./request.ts";
import type { HttpResponse } from "./response.ts";

/** Payload type for each http error. The registry is the only place this package throws. */
type Payloads = {
  RequestFailed: {
    request: HttpRequest.Record;
    reason: "Transport" | "Encode" | "InvalidUrl";
    cause?: unknown;
  };
  ResponseFailed: {
    request: HttpRequest.Record;
    response: HttpResponse.Handle;
    reason: "StatusCode" | "Decode" | "EmptyBody";
    cause?: unknown;
  };
  NoBody: {
    status: number;
  };
};

export declare namespace Errors {
  export type Name = keyof Payloads;
  export type Payload<N extends Name> = Payloads[N];
  export type Of<N extends Name = Name> = Error & {
    readonly kind: N;
    readonly payload: Payloads[N];
  };
}

export function makeError<N extends Errors.Name>(
  kind: N,
  payload: Errors.Payload<N>,
): Errors.Of<N> {
  const error = new Error(kind) as Errors.Of<N>;
  Object.assign(error, { kind, payload });
  return error;
}

/** Throw a registry error where no run ctx is in scope (a body reader). */
export function raise<N extends Errors.Name>(kind: N, payload: Errors.Payload<N>): never {
  throw makeError(kind, payload);
}

/** Throw a registry error through a run's `ctx.raise`, so core stamps its origin at the throw
 * site (ADR 0067). */
export function raiseFrom<N extends Errors.Name>(
  ctx: Pick<Operation.Ctx<unknown>, "raise">,
  kind: N,
  payload: Errors.Payload<N>,
): never {
  return ctx.raise(kind, payload);
}

/** Narrow an unknown error to one registry entry; callers rethrow on mismatch. */
export function isError<N extends Errors.Name>(value: unknown, kind: N): value is Errors.Of<N> {
  return value instanceof Error && (value as Partial<Errors.Of>).kind === kind;
}

export { isError } from "./errors.ts";
export type { Errors } from "./errors.ts";
export { HttpRequest } from "./request.ts";
export { HttpResponse } from "./response.ts";
export type { HttpClient } from "./client.ts";
export {
  applyConfig,
  attempt,
  backend,
  config,
  fetchBackend,
  mergeConfig,
  send,
} from "./client.ts";

export declare namespace HttpRequest {
  export type Method = "GET" | "POST" | "PUT" | "PATCH" | "DELETE" | "HEAD" | "OPTIONS";
  export type Body =
    | { readonly kind: "empty" }
    | { readonly kind: "text"; readonly text: string; readonly contentType: string }
    | { readonly kind: "bytes"; readonly bytes: Uint8Array; readonly contentType: string }
    | { readonly kind: "formData"; readonly formData: FormData }
    | { readonly kind: "urlParams"; readonly params: readonly (readonly [string, string])[] };
  /** An immutable request record: method, raw url, query pairs, fragment, headers (lowercased
   * keys), body. Build with `get`/`post`/... and change with `modify` — always a new record. */
  export type Record = {
    readonly method: Method;
    readonly url: string;
    readonly urlParams: readonly (readonly [string, string])[];
    readonly hash: string | undefined;
    readonly headers: Readonly<globalThis.Record<string, string>>;
    readonly body: Body;
  };
  /** Options for the `get`/`post`/... builders and `modify`: query pairs, fragment, headers
   * (any case, lowercased on the record), a body (a `bodyJson`/`bodyText`/... value), and accept
   * shorthands that set the header. */
  export type Options = {
    readonly urlParams?:
      | Readonly<globalThis.Record<string, string>>
      | readonly (readonly [string, string])[];
    readonly hash?: string;
    readonly headers?: Readonly<globalThis.Record<string, string>>;
    readonly body?: Body;
    readonly accept?: string;
    readonly acceptJson?: boolean;
  };
}

/** A JSON body: text with the JSON content type. A `stringify` failure surfaces as the caller's
 * own error (it is their value that would not serialize). */
export function bodyJson(value: unknown): HttpRequest.Body {
  return { kind: "text", text: JSON.stringify(value), contentType: "application/json" };
}

export function bodyText(text: string, contentType = "text/plain"): HttpRequest.Body {
  return { kind: "text", text, contentType };
}

export function bodyBytes(
  bytes: Uint8Array,
  contentType = "application/octet-stream",
): HttpRequest.Body {
  return { kind: "bytes", bytes, contentType };
}

/** A multipart-form body over the caller's `FormData` (its content type is the transport's). */
export function bodyFormData(formData: FormData): HttpRequest.Body {
  return { kind: "formData", formData };
}

/** A URL-encoded-params body: sent as `URLSearchParams` by `fetchBackend`. */
export function bodyUrlParams(
  params: Readonly<globalThis.Record<string, string>> | readonly (readonly [string, string])[],
): HttpRequest.Body {
  return { kind: "urlParams", params: readPairs(params) };
}

const EMPTY_BODY: HttpRequest.Body = { kind: "empty" };

function readPairs(
  params: Readonly<globalThis.Record<string, string>> | readonly (readonly [string, string])[],
): readonly (readonly [string, string])[] {
  if (Array.isArray(params)) return params;
  return Object.entries(params);
}

function readHeaders(
  headers: Readonly<globalThis.Record<string, string>> | undefined,
): globalThis.Record<string, string> {
  const out: globalThis.Record<string, string> = {};
  if (headers) {
    for (const key of Object.keys(headers)) out[key.toLowerCase()] = headers[key];
  }
  return out;
}

function readAccept(options: HttpRequest.Options | undefined): string | undefined {
  if (options?.accept !== undefined) return options.accept;
  if (options?.acceptJson === true) return "application/json";
  return undefined;
}

function buildRecord(
  method: HttpRequest.Method,
  url: string,
  options: HttpRequest.Options | undefined,
  body: HttpRequest.Body | undefined,
): HttpRequest.Record {
  const headers = readHeaders(options?.headers);
  const accept = readAccept(options);
  if (accept !== undefined) headers.accept = accept;
  const urlParams = options?.urlParams === undefined ? [] : readPairs(options.urlParams);
  return {
    method,
    url,
    urlParams,
    hash: options?.hash,
    headers,
    body: readBody(options, body),
  };
}

function readBody(
  options: HttpRequest.Options | undefined,
  body: HttpRequest.Body | undefined,
): HttpRequest.Body {
  if (body !== undefined) return body;
  return options?.body ?? EMPTY_BODY;
}

export function get(url: string, options?: Omit<HttpRequest.Options, "body">): HttpRequest.Record {
  return buildRecord("GET", url, options, undefined);
}

export function head(url: string, options?: Omit<HttpRequest.Options, "body">): HttpRequest.Record {
  return buildRecord("HEAD", url, options, undefined);
}

export function post(url: string, options?: HttpRequest.Options): HttpRequest.Record {
  return buildRecord("POST", url, options, undefined);
}

export function put(url: string, options?: HttpRequest.Options): HttpRequest.Record {
  return buildRecord("PUT", url, options, undefined);
}

export function patch(url: string, options?: HttpRequest.Options): HttpRequest.Record {
  return buildRecord("PATCH", url, options, undefined);
}

export function del(url: string, options?: HttpRequest.Options): HttpRequest.Record {
  return buildRecord("DELETE", url, options, undefined);
}

export function options(url: string, init?: HttpRequest.Options): HttpRequest.Record {
  return buildRecord("OPTIONS", url, init, undefined);
}

/** Derive a record: `urlParams`, `hash`, and `body` replace; `headers` merge (the option keys
 * win); `accept`/`acceptJson` set the accept header after the merge. Always a new record. */
export function modify(
  request: HttpRequest.Record,
  options: HttpRequest.Options,
): HttpRequest.Record {
  const headers: globalThis.Record<string, string> = { ...request.headers };
  const extra = readHeaders(options.headers);
  for (const key of Object.keys(extra)) headers[key] = extra[key];
  const accept = readAccept(options);
  if (accept !== undefined) headers.accept = accept;
  return {
    method: request.method,
    url: request.url,
    urlParams: options.urlParams === undefined ? request.urlParams : readPairs(options.urlParams),
    hash: options.hash === undefined ? request.hash : options.hash,
    headers,
    body: options.body ?? request.body,
  };
}

/** Prepend a base path by string concatenation (`path + url`, so a base path is kept). */
export function prependUrl(request: HttpRequest.Record, path: string): HttpRequest.Record {
  return { ...request, url: path + request.url };
}

export function appendUrl(request: HttpRequest.Record, path: string): HttpRequest.Record {
  return { ...request, url: request.url + path };
}

export function setHeaders(
  request: HttpRequest.Record,
  headers: Readonly<globalThis.Record<string, string>>,
): HttpRequest.Record {
  const next: globalThis.Record<string, string> = { ...request.headers };
  for (const key of Object.keys(headers)) next[key.toLowerCase()] = headers[key];
  return { ...request, headers: next };
}

export function setHeader(
  request: HttpRequest.Record,
  key: string,
  value: string,
): HttpRequest.Record {
  return { ...request, headers: { ...request.headers, [key.toLowerCase()]: value } };
}

export function setUrlParams(
  request: HttpRequest.Record,
  params: Readonly<globalThis.Record<string, string>> | readonly (readonly [string, string])[],
): HttpRequest.Record {
  return { ...request, urlParams: readPairs(params) };
}

export function toUrl(request: HttpRequest.Record): string {
  let out = request.url;
  if (request.urlParams.length > 0) {
    const params = new URLSearchParams();
    for (const [key, value] of request.urlParams) params.append(key, value);
    out += `?${params.toString()}`;
  }
  if (request.hash !== undefined) out += `#${request.hash}`;
  return out;
}

/** The immutable request-record builders: `HttpRequest.get(...)`, `HttpRequest.bodyJson(...)`. */
export const HttpRequest = {
  get,
  head,
  post,
  put,
  patch,
  del,
  options,
  modify,
  prependUrl,
  appendUrl,
  setHeaders,
  setHeader,
  setUrlParams,
  bodyJson,
  bodyText,
  bodyBytes,
  bodyFormData,
  bodyUrlParams,
  toUrl,
};

import { parse as runParse, type Data } from "@tinker/core";
import { raise } from "./errors.ts";
import type { HttpRequest } from "./request.ts";

export declare namespace HttpResponse {
  /** A received response: status, headers (lowercased keys), the request that produced it, body
   * readers, the adapter's own object (`source`: the web `Response` for `fetchBackend`) for
   * backend-specific reads. Readers delegate to the underlying web `Response` — each consumes the
   * body, so read it once at the process edge. */
  export type Handle = {
    readonly request: HttpRequest.Record;
    readonly status: number;
    readonly headers: Readonly<globalThis.Record<string, string>>;
    readonly source: unknown;
    text(): Promise<string>;
    json(): Promise<unknown>;
    json<T>(parse: HttpResponse.Parse<T>): Promise<T>;
    arrayBuffer(): Promise<ArrayBuffer>;
    formData(): Promise<FormData>;
    stream(): ReadableStream<Uint8Array>;
    /** Server-sent events from the body: WHATWG rules, generic (no `[DONE]` knowledge). */
    sse(): AsyncIterable<HttpResponse.SseEvent>;
  };
  /** One server-sent event: `data` is the joined data lines; `event` and `id` when sent. */
  export type SseEvent = {
    readonly data: string;
    readonly event?: string;
    readonly id?: string;
  };
  /** A body parser for `json(parse)`: validates raw JSON into a trusted value at the process edge. */
  export type Parse<T> = Data.Parse<T>;
  export type Case<R> = (response: Handle) => R;
  /** The cases `matchStatus` dispatches on: exact statuses by number, class buckets, and a
   * fallback. An exact status beats its class bucket; anything unmatched falls to `orElse`. */
  export type Cases<R> = {
    readonly [status: number]: Case<R> | undefined;
    readonly "2xx"?: Case<R>;
    readonly "3xx"?: Case<R>;
    readonly "4xx"?: Case<R>;
    readonly "5xx"?: Case<R>;
    readonly orElse: Case<R>;
  };
  /** Options for {@link make}: status, headers, a body (string, bytes, a byte stream, or null for
   * none), and the adapter's own object when the response wraps one. */
  export type MakeOptions = {
    readonly status: number;
    readonly headers?: Readonly<globalThis.Record<string, string>>;
    readonly body?: string | Uint8Array | ReadableStream<Uint8Array> | null;
    readonly source?: unknown;
  };
}

function readHeaders(headers: Headers): globalThis.Record<string, string> {
  const out: globalThis.Record<string, string> = {};
  headers.forEach((value, key) => {
    out[key.toLowerCase()] = value;
  });
  return out;
}

/** Wrap a web `Response` as a handle: the readers delegate, `source` is the response itself. An
 * empty body reads as `ResponseFailed/EmptyBody` on `json()`; invalid JSON or a throwing `parse`
 * reads as `ResponseFailed/Decode` carrying the `cause`; a missing body raises `NoBody` on
 * `stream()`. */
export function fromWeb(
  request: HttpRequest.Record,
  response: globalThis.Response,
): HttpResponse.Handle {
  const headers = readHeaders(response.headers);
  const status = response.status;
  const readJson = async <T>(parse?: HttpResponse.Parse<T>): Promise<T> => {
    const text = await response.text();
    if (text === "") raise("ResponseFailed", { request, response: handle, reason: "EmptyBody" });
    let raw: unknown;
    try {
      raw = JSON.parse(text);
    } catch (cause) {
      raise("ResponseFailed", { request, response: handle, reason: "Decode", cause });
    }
    if (!parse) return raw as T;
    try {
      return runParse(parse, raw);
    } catch (cause) {
      raise("ResponseFailed", { request, response: handle, reason: "Decode", cause });
    }
  };
  const handle: HttpResponse.Handle = {
    request,
    status,
    headers,
    source: response,
    text: () => response.text(),
    json: <T>(parse?: HttpResponse.Parse<T>): Promise<T> => readJson(parse),
    arrayBuffer: () => response.arrayBuffer(),
    formData: () => response.formData(),
    stream: () => {
      const body = response.body;
      if (body === null) raise("NoBody", { status });
      return body;
    },
    sse: async function* () {
      yield* readSse(handle.stream());
    },
  };
  return handle;
}

/** Build a handle directly: the constructor a custom backend or a test uses. Implemented by
 * building a web `Response` and delegating to {@link fromWeb} — no duplicated reader bodies. */
export function make(
  request: HttpRequest.Record,
  options: HttpResponse.MakeOptions,
): HttpResponse.Handle {
  const response = new Response(readMakeBody(options.body), {
    status: options.status,
    headers: options.headers,
  });
  const handle = fromWeb(request, response);
  return options.source === undefined ? handle : { ...handle, source: options.source };
}

function readMakeBody(
  body: HttpResponse.MakeOptions["body"],
): string | Uint8Array<ArrayBuffer> | ReadableStream<Uint8Array> | null {
  if (body === undefined || body === null) return null;
  return body instanceof Uint8Array ? Uint8Array.from(body) : body;
}

type SseFields = {
  data: string[];
  event: string | undefined;
  id: string | undefined;
};

function readSseField(line: string): { field: string; value: string } {
  const colon = line.indexOf(":");
  if (colon === -1) return { field: line, value: "" };
  const value = line.slice(colon + 1);
  return { field: line.slice(0, colon), value: value.startsWith(" ") ? value.slice(1) : value };
}

function readSseFieldInto(state: SseFields, field: string, value: string): void {
  if (field === "data") state.data.push(value);
  else if (field === "event") state.event = value;
  else if (field === "id") state.id = value;
}

function readSseLine(state: SseFields, line: string): HttpResponse.SseEvent | undefined {
  if (line === "") return dispatchSse(state);
  if (line.startsWith(":")) return undefined;
  const { field, value } = readSseField(line);
  readSseFieldInto(state, field, value);
  return undefined;
}

function dispatchSse(state: SseFields): HttpResponse.SseEvent | undefined {
  const event = state.event;
  const id = state.id;
  const data = state.data.length === 0 ? undefined : state.data.join("\n");
  state.data = [];
  state.event = undefined;
  state.id = undefined;
  if (data === undefined) return undefined;
  const out: { data: string; event?: string; id?: string } = { data };
  if (event !== undefined) out.event = event;
  if (id !== undefined) out.id = id;
  return out;
}

/** Complete lines from the decoded chunks so far, keeping the unfinished tail buffered. A
 * trailing `\r` stays buffered: it may be half of a `\r\n` split across chunks. */
function readSseLines(buffer: string): { lines: string[]; rest: string } {
  const held = buffer.endsWith("\r") ? "\r" : "";
  const lines = buffer.slice(0, buffer.length - held.length).split(/\r\n|\r|\n/);
  const rest = (lines.pop() ?? "") + held;
  return { lines, rest };
}

/** Server-sent events from a byte stream: UTF-8 decoded, split on `\n`, `\r\n`, or `\r`,
 * with the unfinished line kept between chunks and a pending event dispatched at the end. */
async function* readSse(stream: ReadableStream<Uint8Array>): AsyncGenerator<HttpResponse.SseEvent> {
  const reader = stream.getReader();
  const decoder = new TextDecoder();
  const state: SseFields = { data: [], event: undefined, id: undefined };
  let buffer = "";
  try {
    while (true) {
      const next = await reader.read();
      if (next.done) break;
      buffer += decoder.decode(next.value, { stream: true });
      const split = readSseLines(buffer);
      buffer = split.rest;
      yield* readSseEvents(state, split.lines);
    }
    yield* readSseEnd(state, buffer + decoder.decode());
  } finally {
    await reader.cancel();
    reader.releaseLock();
  }
}

function* readSseEvents(
  state: SseFields,
  lines: readonly string[],
): Generator<HttpResponse.SseEvent> {
  for (const line of lines) {
    const event = readSseLine(state, line);
    if (event !== undefined) yield event;
  }
}

function* readSseEnd(state: SseFields, tail: string): Generator<HttpResponse.SseEvent> {
  if (tail !== "") {
    const event = readSseLine(state, tail);
    if (event !== undefined) yield event;
  }
  const last = dispatchSse(state);
  if (last !== undefined) yield last;
}

export const HttpResponse = { fromWeb, make, filterStatus, filterStatusOk, matchStatus };

/** Pass the response through when `accept(status)` holds, else raise `ResponseFailed/StatusCode`
 * carrying `request` and `response` (the body stays readable by a catch handler). */
export function filterStatus(
  response: HttpResponse.Handle,
  accept: (status: number) => boolean,
): HttpResponse.Handle {
  if (accept(response.status)) return response;
  raise("ResponseFailed", {
    request: response.request,
    response,
    reason: "StatusCode",
  });
}

/** `filterStatus` with the 2xx range — Effect's `filterStatusOk` shape, no `pipe`. */
export function filterStatusOk(response: HttpResponse.Handle): HttpResponse.Handle {
  return filterStatus(response, (status) => status >= 200 && status < 300);
}

/** Read a response into a value by status: an exact status beats its class bucket
 * (`"2xx"`/`"3xx"`/`"4xx"`/`"5xx"` by hundreds digit), anything unmatched falls to `orElse`.
 * The return type is the union of the case results (Effect's shape, no `Unify`). */
export function matchStatus<R>(response: HttpResponse.Handle, cases: HttpResponse.Cases<R>): R {
  const exact = cases[response.status];
  if (exact !== undefined) return exact(response);
  const bucket = readBucket(cases, response.status);
  if (bucket !== undefined) return bucket(response);
  return cases.orElse(response);
}

function readBucket<R>(
  cases: HttpResponse.Cases<R>,
  status: number,
): HttpResponse.Case<R> | undefined {
  const klass = Math.floor(status / 100);
  if (klass === 2) return cases["2xx"];
  if (klass === 3) return cases["3xx"];
  if (klass === 4) return cases["4xx"];
  if (klass === 5) return cases["5xx"];
  return undefined;
}
